#!/usr/bin/env node
/**
 * Copy the @webjsdev/ui registry component sources into this site's
 * components/ui/ (plus the kit's lib/ into lib/ui/) so the /ui gallery
 * pages can import them and render live previews.
 *
 * Both destinations are gitignored: they mirror the canonical sources in
 * packages/ui/packages/registry/, regenerated by webjs.dev.before /
 * webjs.start.before and baked into the deploy image at build time (the
 * `bun webjs.js start` form bypasses npm hooks). Hand-written site
 * components stay in components/*.ts and lib/*.ts, which are tracked
 * normally; only the ui/ subdirectories are generated.
 *
 * Each component's relative `../lib/utils.ts` / `../lib/dom.ts` import
 * (the registry's local layout) is rewritten to `../../lib/ui/*` (this
 * site's layout: `components/ui/<name>.ts` is two levels above `lib/ui/`).
 * Missing the dom.ts rewrite 500s SSR (#819).
 */
import { readFileSync, writeFileSync, readdirSync, mkdirSync, existsSync, copyFileSync, rmSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const SITE_ROOT = resolve(__dirname, '..');
const REGISTRY_ROOT = resolve(SITE_ROOT, '..', 'packages', 'ui', 'packages', 'registry');

const COMPONENTS_SRC = join(REGISTRY_ROOT, 'components');
const LIB_SRC = join(REGISTRY_ROOT, 'lib', 'utils.ts');
// onBeforeCache lives in its own client-only module since the #819 split.
const LIB_DOM_SRC = join(REGISTRY_ROOT, 'lib', 'dom.ts');

const COMPONENTS_DST = join(SITE_ROOT, 'components', 'ui');
const LIB_DST_DIR = join(SITE_ROOT, 'lib', 'ui');

if (!existsSync(COMPONENTS_SRC)) {
  console.error(`[website] ui registry components not found at ${COMPONENTS_SRC}`);
  process.exit(1);
}

mkdirSync(COMPONENTS_DST, { recursive: true });
mkdirSync(LIB_DST_DIR, { recursive: true });

// Clean the destination so removed-from-registry components don't linger as
// orphans (they'd still be importable from site code and confuse SSR / the
// dev server's module graph). Only .ts files are managed here.
for (const name of readdirSync(COMPONENTS_DST)) {
  if (name.endsWith('.ts')) rmSync(join(COMPONENTS_DST, name));
}

copyFileSync(LIB_SRC, join(LIB_DST_DIR, 'utils.ts'));
copyFileSync(LIB_DOM_SRC, join(LIB_DST_DIR, 'dom.ts'));

let copied = 0;
for (const name of readdirSync(COMPONENTS_SRC)) {
  if (!name.endsWith('.ts')) continue;
  const raw = readFileSync(join(COMPONENTS_SRC, name), 'utf8');
  const rewritten = raw
    .replaceAll("'../lib/utils.ts'", "'../../lib/ui/utils.ts'")
    .replaceAll('"../lib/utils.ts"', '"../../lib/ui/utils.ts"')
    .replaceAll("'../lib/dom.ts'", "'../../lib/ui/dom.ts'")
    .replaceAll('"../lib/dom.ts"', '"../../lib/ui/dom.ts"');
  writeFileSync(join(COMPONENTS_DST, name), rewritten);
  copied++;
}

console.log(`[website] copied ${copied} ui components + lib/ui/{utils,dom}.ts from the registry`);
